settings.liquid:
{%- assign path = request.path | downcase -%}
{%- assign locale_code = localization.language.iso_code | default: shop.locale | default: 'en' | downcase -%}

{%- assign customers_say_label = 'Customers say:' -%}
{%- if path contains '/nl' or locale_code contains 'nl' -%}
  {%- assign customers_say_label = 'Klanten zeggen:' -%}
{%- elsif path contains '/de' or locale_code contains 'de' -%}
  {%- assign customers_say_label = 'Kundinnen sagen:' -%}
{%- endif -%}

<div class="cj-customers-say">
  <strong>{{ customers_say_label }}</strong>
  <div class="cj-customers-say__value">
    {{ product.metafields.shopify.fit | metafield_tag: field: 'label' }}
  </div>
</div>

<style>
  .cj-customers-say{
    margin:0 0 16px;
    font-size:14px;
    line-height:1.35;
    color:#111;
  }

  .cj-customers-say__value{
    margin-top:4px;
  }

  .cj-customers-say__value,
  .cj-customers-say__value *{
    display:block;
    margin-bottom:0;
  }
</style>

{% assign sale_enabled = product.metafields.custom.sale_enabled.value | default: false %}

{% unless sale_enabled %}
  <div style="height:16px;"></div>
{% endunless %}
